@props(['values','label'=>'Total','links'=>[],'palette'=>['#5269db','#eb5794','#58b765','#f2ba45','#29a4bd','#9260cd','#f48354','#a8b9db']])
<?php $values=collect($values); $total=$values->sum(); $offset=0; ?>
<div class="hr-donut-wrap"><svg viewBox="0 0 150 150" class="hr-donut" role="img" aria-label="{{ $label }}: {{ number_format($total) }}"><circle cx="75" cy="75" r="52" fill="none" stroke="#edf0f7" stroke-width="26"/>@foreach($values as $name=>$value)<?php $share=$total?$value/$total*100:0; ?>@if(isset($links[$name]))<a href="{{ $links[$name] }}" aria-label="View {{ $name }}: {{ $value }}">@endif<circle cx="75" cy="75" r="52" pathLength="100" fill="none" stroke="{{ $palette[$loop->index%count($palette)] }}" stroke-width="26" stroke-dasharray="{{ $share }} {{ 100-$share }}" stroke-dashoffset="{{ -$offset }}" transform="rotate(-90 75 75)"/><title>{{ $name }}: {{ $value }}</title>@if(isset($links[$name]))</a>@endif<?php $offset+=$share; ?>@endforeach<text x="75" y="74" text-anchor="middle" font-size="19" font-weight="600" fill="#17243d">{{ number_format($total) }}</text><text x="75" y="89" text-anchor="middle" font-size="9" fill="#6d7890">{{ $label }}</text></svg><div class="hr-legend">@foreach($values as $name=>$value)<div><i style="background:{{ $palette[$loop->index%count($palette)] }}"></i><span>@if(isset($links[$name]))<a href="{{ $links[$name] }}">{{ ucfirst(str_replace('_',' ',$name)) }}</a>@else{{ ucfirst(str_replace('_',' ',$name)) }}@endif</span><strong>{{ number_format($value) }} <small>({{ $total?round($value/$total*100):0 }}%)</small></strong></div>@endforeach @if(!$total)<p>No counts recorded.</p>@endif</div></div>
